local defaults = {
    solo=3, group=3, journey=3, endgame=3, sessionEase=3, mastery=3, power=3,
    flexibility=2, attachment=3, identity=3, roleDamage=0, roleTank=0, roleHeal=0, roleFlex=1,
    rangePhysical=0, rangeSpell=0, melee=0, mobility=2, stationaryTolerance=3,
    control=2, survivability=3, recovery=2, burst=3, sustain=3, utility=3,
    multiTarget=2, slowRhythm=2, fastRhythm=2, tactical=3, reactive=2,
    complexity=3, maintenance=2, pet=0, pvp=3,
    fantasyHunter=0, fantasyRogue=0, fantasyWarrior=0, fantasyHoly=0,
    fantasyCaster=0, fantasyDark=0, fantasyNature=0, fantasyElements=0, fantasyPriest=0,
}

local function Profile(class, spec, role, values, summary, frustrations, evidence)
    local ratings = {}
    for key, value in pairs(defaults) do ratings[key] = value end
    for key, value in pairs(values) do ratings[key] = value end
    return {
        id = class:lower() .. "_" .. spec:lower():gsub("[^a-z]+", "_"),
        class = class, className = NS.classNames[class], spec = spec, role = role,
        ratings = ratings, summary = summary, frustrations = frustrations,
        evidence = evidence, provisional = true,
    }
end

